      dmsg(
          {
              and        => eval { $opts{find} and $opts{find} = 's' },
              postfix_if => eval { $opts{find} = 's' if $opts{find} }
          }
      );
  
      const my %fields => (
          base                 => '%e',
          arch                 => '%a',
          backup_files         => '%B',
          build_date           => '%b',
