$fatpacked{"Const/Fast.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'CONST_FAST';
  package Const::Fast;
  {
    $Const::Fast::VERSION = '0.014';
  }
  
  use 5.008;
  use strict;
  use warnings FATAL => 'all';
  
  use Scalar::Util qw/reftype blessed/;
  use Carp qw/croak/;
  use Sub::Exporter::Progressive 0.001007 -setup => { exports => [qw/const/], groups => { default => [qw/const/] } };
  
  sub _dclone($) {
  	require Storable;
  	no warnings 'redefine';
  	*_dclone = \&Storable::dclone;
  	goto &Storable::dclone;
  }
  
  ## no critic (RequireArgUnpacking, ProhibitAmpersandSigils)
  # The use of $_[0] is deliberate and essential, to be able to use it as an lvalue and to keep the refcount down.
  
  my %skip = map { $_ => 1 } qw/CODE GLOB/;
  
  sub _make_readonly {
  	my (undef, $dont_clone) = @_;
  	if (my $reftype = reftype $_[0] and not blessed($_[0]) and not &Internals::SvREADONLY($_[0])) {
  		$_[0] = _dclone($_[0]) if !$dont_clone && &Internals::SvREFCNT($_[0]) > 1 && !$skip{$reftype};
  		&Internals::SvREADONLY($_[0], 1);
  		if ($reftype eq 'SCALAR' || $reftype eq 'REF') {
  			_make_readonly(${ $_[0] }, 1);
  		}
  		elsif ($reftype eq 'ARRAY') {
  			_make_readonly($_) for @{ $_[0] };
  		}
  		elsif ($reftype eq 'HASH') {
  			&Internals::hv_clear_placeholders($_[0]);
  			_make_readonly($_) for values %{ $_[0] };
  		}
  	}
  	Internals::SvREADONLY($_[0], 1);
  	return;
  }
  
  ## no critic (ProhibitSubroutinePrototypes, ManyArgs)
  sub const(\[$@%]@) {
  	my (undef, @args) = @_;
  	croak 'Invalid first argument, need an reference' if not defined reftype($_[0]);
  	croak 'Attempt to reassign a readonly variable' if &Internals::SvREADONLY($_[0]);
  	if (reftype $_[0] eq 'SCALAR' or reftype $_[0] eq 'REF') {
  		croak 'No value for readonly variable' if @args == 0;
  		croak 'Too many arguments in readonly assignment' if @args > 1;
  		${ $_[0] } = $args[0];
  	}
  	elsif (reftype $_[0] eq 'ARRAY') {
  		@{ $_[0] } = @args;
  	}
  	elsif (reftype $_[0] eq 'HASH') {
  		croak 'Odd number of elements in hash assignment' if @args % 2;
  		%{ $_[0] } = @args;
  	}
  	else {
  		croak 'Can\'t make variable readonly';
  	}
  	_make_readonly($_[0], 1);
  	return;
  }
  
  1;    # End of Const::Fast
  
  # ABSTRACT: Facility for creating read-only scalars, arrays, and hashes
  
  __END__
  
  =pod
  
  =head1 NAME
  
  Const::Fast - Facility for creating read-only scalars, arrays, and hashes
  
  =head1 VERSION
  
  version 0.014
  
  =head1 SYNOPSIS
  
   use Const::Fast;
  
   const my $foo => 'a scalar value';
   const my @bar => qw/a list value/;
   const my %buz => (a => 'hash', of => 'something');
  
  =head1 SUBROUTINES/METHODS
  
  =head2 const $var, $value
  
  =head2 const @var, @value...
  
  =head2 const %var, %value...
  
  This the only function of this module and it is exported by default. It takes a scalar, array or hash lvalue as first argument, and a list of one or more values depending on the type of the first argument as the value for the variable. It will set the variable to that value and subsequently make it readonly. Arrays and hashes will be made deeply readonly.
  
  Exporting is done using Sub::Exporter::Progressive. You may need to depend on Sub::Exporter explicitly if you need the latter's flexibility.
  
  =head1 RATIONALE
  
  This module was written because I stumbled on some serious issues of L<Readonly> that aren't easily fixable without breaking backwards compatibility in subtle ways. In particular Readonly's use of ties is a source of subtle bugs and bad performance. Instead, this module uses the builtin readonly feature of perl, making access to the variables just as fast as any normal variable without the weird side-effects of ties. Readonly can do the same for scalars when Readonly::XS is installed, but chooses not to do so in the most common case. This may change in the future if someone takes up maintenance of Readonly, and the two modules may be convergence if that happens.
  
  =head1 CAVEATS
  
  Perl doesn't distinguish between restricted hashes and readonly hashes. This means that:
  
   use Const::Fast;
   const my %a => (foo => 1, bar => 2);
   say 1 unless $a{baz}
  
  Will give the error "Attempt to access disallowed key 'baz' in a restricted hash". You have to use C<exists $a{baz}> instead. This is a limitation of perl that can hopefully be solved in the future.
  
  =head1 ACKNOWLEDGEMENTS
  
  The interface for this module was inspired by Eric Roode's L<Readonly>. The implementation is inspired by doing everything the opposite way Readonly does it.
  
  =head1 AUTHOR
  
  Leon Timmermans <fawaka@gmail.com>
  
  =head1 COPYRIGHT AND LICENSE
  
  This software is copyright (c) 2010 by Leon Timmermans.
  
  This is free software; you can redistribute it and/or modify it under
  the same terms as the Perl 5 programming language system itself.
  
  =cut
CONST_FAST

$fatpacked{"Const/Fast/Exporter.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'CONST_FAST_EXPORTER';
  package Const::Fast::Exporter;
  $Const::Fast::Exporter::VERSION = '0.02';
  require 5.010;
  
  use strict;
  use warnings;
  use Const::Fast;
  
  my %is_readonly = (
      SCALAR => sub { Internals::SvREADONLY(${ $_[0] }) },
      HASH   => sub { Internals::SvREADONLY(%{ $_[0] }) },
      ARRAY  => sub { Internals::SvREADONLY(@{ $_[0] }) },
  );
  
  my @TYPES = keys %is_readonly;
  
  #=======================================================================
  # This is the import function that we put in the module which is
  # exporting const::fast variables. We look for all const variables
  # and export them into the namespace that use'd the constants module.
  #
  # NOTE:
  # when @FOOBAR is defined, the glob will also have *{...::FOOBAR}{SCALAR}
  # defined. This is due to an assumption made in early versions of Perl 5.
  # So we find all names in the symbol table, and then check whether
  # (a) the relevant glob slot is filled, and then (b) whether the package
  # variable has been marked as readonly (i.e. looks to be a Const::Fast
  # immutable variable. If so, then we export it.
  #
  # Another approach would be to use Package::Stash::has_symbol('@FOOBAR'),
  # or if we wanted to keep the number of dependencies down, we could
  # lift the code here:
  #  https://metacpan.org/source/DOY/Package-Stash-0.37/lib/Package/Stash/PP.pm#L244-256
  # Thanks to HAARG and Nicholas, who answered questions about this on #p5p
  #=======================================================================
  
  my $immutable_variables_exporter = sub {
      my $exporting_package = shift;
      my $importing_package = caller();
      my $symbol_table_ref  = eval "\\\%${exporting_package}::";
  
      foreach my $variable (keys %$symbol_table_ref) {
          foreach my $type (@TYPES) {
              no strict 'refs';
              my $globref = *{"${exporting_package}::${variable}"}{$type};
              if (defined($globref) && &{ $is_readonly{$type} }($globref)) {
                  *{"${importing_package}::${variable}"} = $globref;
              }
          }
      }
  };
  
  #=======================================================================
  # When someone uses Const::Fast::Exporter we drop Const::Fast::const
  # into their namespace (so they don't have to use Const::Fast as well)
  # and we also give their package an import() function, which will
  # export all Const::Fast read-only variables.
  #=======================================================================
  sub import
  {
      my $exporting_package = shift;
      my $importing_package = caller();
  
      no strict 'refs';
  
      *{"${importing_package}::const"} = *{"Const::Fast::const"}{CODE};
      *{"${importing_package}::import"} = $immutable_variables_exporter;
  }
  
  1;
  
  =head1 NAME
  
  Const::Fast::Exporter - create a module that exports Const::Fast immutable variables
  
  =head1 SYNOPSIS
  
  Create your module that defines the constants:
  
   package MyConstants;
   use Const::Fast::Exporter;
  
   const our $ANSWER => 42;
   const our @COLORS => qw/ red green blue /;
   const our %ORIGIN => { x => 0, y => 0 };
  
   1;
  
  And then to use the constants:
  
   use MyConstants;
  
   print "The answer = $ANSWER\n";
  
  =head1 DESCRIPTION
  
  This module is helpful if you want to create a module
  that defines L<Const::Fast> immutable variables, 
  which are then exported.
  The SYNOPSIS provides just about everything you need to know.
  When you use C<Const::Fast::Exporter>,
  it loads C<Const::Fast> for you,
  which is why there isn't a C<use Const::Fast> line in the SYNOPSIS.
  
  B<Note:> the interface should be considered unstable.
  At the moment it is very simple -- it just exports all symbols.
  Possibly there should be an option to specify whether everything is an optional export, with a C<-all> switch. Maybe you'd do something like:
  
   use Const::Fast::Exporter -requested;
  
  Which says that people have to specifically request the constants they want,
  rather than getting all of them by default.
  
  If you want to define tags,
  then you should probably just use L<Exporter> or similar.
  
  
  =head1 SEE ALSO
  
  L<Const::Fast> - lets you define read-only scalars, hashes, and arrays.
  
  L<Const::Exporter> - another module you can use to create your
  own module that exports constant and immutable variables.
  
  L<Exporter::Constants> - declare and export function-based constants,
  similar to those declared with the L<constant> pragma.
  
  L<Constant::Exporter> - declare and export function-based constants.
  
  L<Constant::Export::Lazy> - create a module that exports constants,
  where the value is only generated the first time its used.
  
  =head1 REPOSITORY
  
  L<https://github.com/neilb/Const-Fast-Exporter>
  
  
  =head1 AUTHOR
  
  Neil Bowers E<lt>neilb@cpan.orgE<gt>
  
  
  =head1 COPYRIGHT AND LICENSE
  
  This software is copyright (c) 2017 by Neil Bowers <neilb@cpan.org>.
  
  This is free software; you can redistribute it and/or modify it under
  the same terms as the Perl 5 programming language system itself.
  
  =cut
  
CONST_FAST_EXPORTER

$fatpacked{"Devel/StackTrace.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'DEVEL_STACKTRACE';
  package Devel::StackTrace;
  
  use 5.006;
  
  use strict;
  use warnings;
  
  our $VERSION = '2.05';
  
  use Devel::StackTrace::Frame;
  use File::Spec;
  use Scalar::Util qw( blessed );
  
  use overload
      '""'     => \&as_string,
      bool     => sub {1},
      fallback => 1;
  
  sub new {
      my $class = shift;
      my %p     = @_;
  
      $p{unsafe_ref_capture} = !delete $p{no_refs}
          if exists $p{no_refs};
  
      my $self = bless {
          index  => undef,
          frames => [],
          raw    => [],
          %p,
      }, $class;
  
      $self->_record_caller_data;
  
      return $self;
  }
  
  sub _record_caller_data {
      my $self = shift;
  
      my $filter = $self->{filter_frames_early} && $self->_make_frame_filter;
  
      # We exclude this method by starting at least one frame back.
      my $x = 1 + ( $self->{skip_frames} || 0 );
  
      while (
          my @c
          = $self->{no_args}
          ? caller( $x++ )
          : do {
              ## no critic (Modules::ProhibitMultiplePackages, Variables::ProhibitPackageVars)
              package    # the newline keeps dzil from adding a version here
                  DB;
              @DB::args = ();
              caller( $x++ );
          }
      ) {
  
          my @args;
  
          ## no critic (Variables::ProhibitPackageVars, BuiltinFunctions::ProhibitComplexMappings)
          unless ( $self->{no_args} ) {
  
              # This is the same workaroud as was applied to Carp.pm a little
              # while back
              # (https://rt.perl.org/Public/Bug/Display.html?id=131046):
              #
              #   Guard our serialization of the stack from stack refcounting
              #   bugs NOTE this is NOT a complete solution, we cannot 100%
              #   guard against these bugs. However in many cases Perl *is*
              #   capable of detecting them and throws an error when it
              #   does. Unfortunately serializing the arguments on the stack is
              #   a perfect way of finding these bugs, even when they would not
              #   affect normal program flow that did not poke around inside the
              #   stack. Inside of Carp.pm it makes little sense reporting these
              #   bugs, as Carp's job is to report the callers errors, not the
              #   ones it might happen to tickle while doing so.  See:
              #   https://rt.perl.org/Public/Bug/Display.html?id=131046 and:
              #   https://rt.perl.org/Public/Bug/Display.html?id=52610 for more
              #   details and discussion. - Yves
              @args = map {
                  my $arg;
                  local $@ = $@;
                  eval {
                      $arg = $_;
                      1;
                  } or do {
                      $arg = '** argument not available anymore **';
                  };
                  $arg;
              } @DB::args;
          }
          ## use critic
  
          my $raw = {
              caller => \@c,
              args   => \@args,
          };
  
          next if $filter && !$filter->($raw);
  
          unless ( $self->{unsafe_ref_capture} ) {
              $raw->{args} = [ map { ref $_ ? $self->_ref_to_string($_) : $_ }
                      @{ $raw->{args} } ];
          }
  
          push @{ $self->{raw} }, $raw;
      }
  }
  
  sub _ref_to_string {
      my $self = shift;
      my $ref  = shift;
  
      return overload::AddrRef($ref)
          if blessed $ref && $ref->isa('Exception::Class::Base');
  
      return overload::AddrRef($ref) unless $self->{respect_overload};
  
      ## no critic (Variables::RequireInitializationForLocalVars)
      local $@;
      local $SIG{__DIE__};
      ## use critic
  
      my $str = eval { $ref . q{} };
  
      return $@ ? overload::AddrRef($ref) : $str;
  }
  
  sub _make_frames {
      my $self = shift;
  
      my $filter = !$self->{filter_frames_early} && $self->_make_frame_filter;
  
      my $raw = delete $self->{raw};
      for my $r ( @{$raw} ) {
          next if $filter && !$filter->($r);
  
          $self->_add_frame( $r->{caller}, $r->{args} );
      }
  }
  
  my $default_filter = sub {1};
  
  sub _make_frame_filter {
      my $self = shift;
  
      my ( @i_pack_re, %i_class );
      if ( $self->{ignore_package} ) {
          ## no critic (Variables::RequireInitializationForLocalVars)
          local $@;
          local $SIG{__DIE__};
