  # Don't "use constant" here, to avoid dependencies.
  BEGIN {
      ## no critic (ValuesAndExpressions::ProhibitMismatchedOperators)
      *_WORK_AROUND_HINT_LEAKAGE =
          "$]" < 5.011 && !("$]" >= 5.009004 && "$]" < 5.010001)
