  package List::SomeUtils::XS;
  
  use 5.006;
  use strict;
  use warnings;
  
  our $VERSION = '0.58';
  
  require XSLoader;
  XSLoader::load( __PACKAGE__, $VERSION );
  
  require List::SomeUtils::PP;
  
  # This list is copied from List::SomeUtils itself and should be updated
  # when subs are added.
  my @subs = qw(
      after
      after_incl
      all
      all_u
      any
      any_u
      apply
      before
      before_incl
      bsearch
      bsearchidx
      each_array
      each_arrayref
      false
      firstidx
      firstres
      firstval
      indexes
      insert_after
      insert_after_string
      lastidx
      lastres
      lastval
      mesh
      minmax
      mode
      natatime
      none
      none_u
      notall
      notall_u
      nsort_by
      one
      one_u
      onlyidx
      onlyres
      onlyval
      pairwise
      part
      singleton
      sort_by
      true
      uniq
  );
  
  for my $sub (@subs) {
      next if __PACKAGE__->can($sub);
      ## no critic (TestingAndDebugging::ProhibitNoStrict)
      no strict 'refs';
      *{$sub} = List::SomeUtils::PP->can($sub);
  }
  
  1;
  
  # ABSTRACT: XS implementation for List::SomeUtils
  
  __END__
  
