$fatpacked{"x86_64-linux-thread-multi/Object/Pad/MetaFunctions.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'X86_64-LINUX-THREAD-MULTI_OBJECT_PAD_METAFUNCTIONS';
  #  You may distribute under the terms of either the GNU General Public License
  #  or the Artistic License (the same terms as Perl itself)
  #
  #  (C) Paul Evans, 2022 -- leonerd@leonerd.org.uk
  
  package Object::Pad::MetaFunctions 0.821;
  
  use v5.18;
  use warnings;
  
  use Exporter 'import';
  our @EXPORT_OK = qw(
     metaclass
     deconstruct_object
     ref_field
     get_field
  );
  
  BEGIN {
     if( defined &builtin::reftype ) {
        warnings->unimport( 'experimental::builtin' );
        builtin->import(qw( reftype ));
     }
     else {
        require Scalar::Util;
        Scalar::Util->import(qw( reftype ));
     }
  }
  
  =head1 NAME
  
  C<Object::Pad::MetaFunctions> - utility functions for C<Object::Pad> classes
  
  =head1 SYNOPSIS
  
  =for highlighter language=perl
  
     use v5.36;
     use Object::Pad::MetaFunctions qw( deconstruct_object );
  
     sub debug_print_object ( $obj )
     {
        my ( $classname, @repr ) = deconstruct_object( $obj );
  
        say "An object of type $classname having:";
  
        foreach my ( $fieldname, $value ) ( @repr ) {
           printf "%30s = %s\n", $fieldname, $value;
        }
     }
  
  =head1 DESCRIPTION
  
  This module contains a number of miscellaneous utility functions for working
  with L<Object::Pad>-based classes or instances thereof.
  
  These functions all involve a certain amount of encapsulation-breaking into
  the object instances being operated on. This sort of thing shouldn't be
  encouraged in most regular code, but there can be occasions when it is useful;
  such as debug printing of values, generic serialisation, or tightly-coupled
  unit tests that wish to operate on the internals of the object instances they
  test.
  
  Therefore, use of these functions should be considered "last-resort". Consider
  carefully the sorts of things you are trying to do with them, and whether this
  kind of reaching into the internals of an object, bypassing all of its
  interface encapsulation, is really the best technique to achieve your goal.
  
  =head1 FUNCTIONS
  
  =cut
  
  =head2 metaclass
  
     $metaclass = metaclass( $obj );
  
  I<Since version 0.67.>
  
  Returns the L<Object::Pad::MOP::Class> metaclass associated with the class
  that the object is an instance of.
  
  =head2 deconstruct_object
  
     ( $classname, @repr ) = deconstruct_object( $obj );
  
  I<Since version 0.67.>
  
  Returns a list of perl values containing a representation of all the fields in
  the object instance. This representation form may be useful for tasks such as
  debug printing or serialisation of the instance. This list is prefixed by the
  name of the class of instance as a plain string.
  
  The exact form of this representation is still experimental and may change in
  a later version. Currently, it takes the form of an even-sized list of
  key/value pairs, associating field names with their values. Each key gives the
  name of a component class and the full name of the field within it, separated
  by a dot (C<.>).
  
     'CLASSNAME.$FIELD1' => VALUE, 'CLASSNAME.@FIELD2' => VALUE, ...
  
  In the case of scalar fields, the value is the actual value of that field. In
  the case of array or hash fields, the value in the repr list is a reference to
  an anonymous I<copy of> the value stored in the field.
  
     'CLASSNAME.$SCALARFIELD' => $VALUE,
     'CLASSNAME.@ARRAYFIELD'  => [ @VALUE ],
     'CLASSNAME.%HASHFIELD'   => { %VALUE },
  
  The pairs are ordered, with the actual object class type first, followed by
  any roles added by that class, then each parent class recursively. Within each
  component class, the fields are given in declared order.
  
  This reliable ordering may be useful when printing values in human-readable
  form, or serialising to some stable storage.
  
  =head2 ref_field
  
     $fieldref = ref_field( $fieldname, $obj );
  
  I<Since version 0.67.>
  
  Returns a reference to the named field storage variable of the given instance
  object. The I<$fieldname> should be specified as the class name and the field
  name separated by a dot (C<.>) (as per L</deconstruct_object>).
  
  The class name may also be omitted; at which point the first occurrence of a
  field of the given name found in any component class it matched instead.
  
  If no matching field is found, an exception is thrown.
  
  Be careful when using this function as it has the ability to expose instance
  fields in a way that allows them to be modified. For a safer alternative when
  only read access is required, use L</get_field> instead.
  
  =cut
  
  =head2 get_field
  
     $scalar = get_field( $fieldname, $obj );
     @array  = get_field( $fieldname, $obj );
     %hash   = get_field( $fieldname, $obj );
  
  I<Since version 0.67.>
  
  Returns the value of the named field of the given instance object. Behaves
  correctly given context; namely, that when invoked on array or hash fields in
  scalar context it will return the number of elements or keys, or in list
  context will return the list of elements or key/value pairs.
  
  =cut
  
  sub get_field
  {
     my $ref = ref_field( @_ );
     my $type = reftype $ref;
     return @$ref if $type eq "ARRAY";
     return %$ref if $type eq "HASH";
     return $$ref;
  }
  
  =head1 AUTHOR
  
  Paul Evans <leonerd@leonerd.org.uk>
  
  =cut
  
  0x55AA;
X86_64-LINUX-THREAD-MULTI_OBJECT_PAD_METAFUNCTIONS

$fatpacked{"x86_64-linux-thread-multi/PadWalker.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'X86_64-LINUX-THREAD-MULTI_PADWALKER';
  package PadWalker;
  
  use strict;
  use vars qw($VERSION @ISA @EXPORT_OK %EXPORT_TAGS);
  
  require Exporter;
  require DynaLoader;
  
  require 5.008;
  
  @ISA = qw(Exporter DynaLoader);
  @EXPORT_OK = qw(peek_my peek_our closed_over peek_sub var_name set_closed_over);
  %EXPORT_TAGS = (all => \@EXPORT_OK);
  
  $VERSION = '2.5';
  
  bootstrap PadWalker $VERSION;
  
  sub peek_my;
  sub peek_our;
  sub closed_over;
  sub peek_sub;
  sub var_name;
  
  1;
  __END__
  
  =head1 NAME
  
  PadWalker - play with other peoples' lexical variables
  
  =head1 SYNOPSIS
  
    use PadWalker qw(peek_my peek_our peek_sub closed_over);
    ...
  
  =head1 DESCRIPTION
  
  PadWalker is a module which allows you to inspect (and even change!)
  lexical variables in any subroutine which called you. It will only
  show those variables which are in scope at the point of the call.
  
  PadWalker is particularly useful for debugging. It's even
  used by Perl's built-in debugger. (It can also be used
  for evil, of course.)
  
  I wouldn't recommend using PadWalker directly in production
  code, but it's your call. Some of the modules that use
  PadWalker internally are certainly safe for and useful
  in production.
  
  =over 4
  
  =item peek_my LEVEL
  
  =item peek_our LEVEL
  
  The LEVEL argument is interpreted just like the argument to C<caller>.
  So C<peek_my(0)> returns a reference to a hash of all the C<my>
  variables that are currently in scope;
  C<peek_my(1)> returns a reference to a hash of all the C<my>
  variables that are in scope at the point where the current
  sub was called, and so on.
  
  C<peek_our> works in the same way, except that it lists
  the C<our> variables rather than the C<my> variables.
  
  The hash associates each variable name with a reference
  to its value. The variable names include the sigil, so
  the variable $x is represented by the string '$x'.
  
  For example:
  
    my $x = 12;
    my $h = peek_my (0);
    ${$h->{'$x'}}++;
  
    print $x;  # prints 13
  
  Or a more complex example:
  
    sub increment_my_x {
      my $h = peek_my (1);
      ${$h->{'$x'}}++;
    }
  
    my $x=5;
    increment_my_x;
    print $x;  # prints 6
  
  =item peek_sub SUB
  
  The C<peek_sub> routine takes a coderef as its argument, and returns a hash
  of the C<my> variables used in that sub. The values will usually be undefined
  unless the sub is in use (i.e. in the call-chain) at the time. On the other
  hand:
  
    my $x = "Hello!";
    my $r = peek_sub(sub {$x})->{'$x'};
    print "$$r\n";	# prints 'Hello!'
  
  If the sub defines several C<my> variables with the same name, you'll get the
  last one. I don't know of any use for C<peek_sub> that isn't broken as a result
  of this, and it will probably be deprecated in a future version in favour of
  some alternative interface.
  
  =item closed_over SUB
  
  C<closed_over> is similar to C<peek_sub>, except that it only lists
  the C<my> variables which are used in the subroutine but defined outside:
  in other words, the variables which it closes over. This I<does> have
  reasonable uses: see L<Data::Dump::Streamer>, for example (a future version
  of which may in fact use C<closed_over>).
  
  =item set_closed_over SUB, HASH_REF
  
  C<set_closed_over> reassigns the pad variables that are closed over by the subroutine.
  
  The second argument is a hash of references, much like the one returned from C<closed_over>.
  
  =item var_name LEVEL, VAR_REF
  
  =item var_name SUB,   VAR_REF
  
  C<var_name(sub, var_ref)> returns the name of the variable referred to
  by C<var_ref>, provided it is a C<my> variable used in the sub. The C<sub>
  parameter can be either a CODE reference or a number. If it's a number,
  it's treated the same way as the argument to C<peek_my>.
  
  For example,
  
    my $foo;
    print var_name(0, \$foo);    # prints '$foo'
    
    sub my_name {
      return var_name(1, shift);
    }
    print my_name(\$foo);        # ditto
  
  =back
  
  =head1 AUTHOR
  
  Robin Houston <robin@cpan.org>
  
  With contributions from Richard Soberberg, Jesse Luehrs and
  Yuval Kogman, bug-spotting from Peter Scott, Dave Mitchell and
  Goro Fuji, and suggestions from demerphq.
  
  =head1 SEE ALSO
  
  Devel::LexAlias, Devel::Caller, Sub::Parameters
  
  =head1 COPYRIGHT
  
  Copyright (c) 2000-2009, Robin Houston. All Rights Reserved.
  This module is free software. It may be used, redistributed
  and/or modified under the same terms as Perl itself.
  
  =cut
X86_64-LINUX-THREAD-MULTI_PADWALKER

$fatpacked{"x86_64-linux-thread-multi/Sublike/Extended.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'X86_64-LINUX-THREAD-MULTI_SUBLIKE_EXTENDED';
  #  You may distribute under the terms of either the GNU General Public License
  #  or the Artistic License (the same terms as Perl itself)
  #
  #  (C) Paul Evans, 2023-2024 -- leonerd@leonerd.org.uk
  
  package Sublike::Extended 0.39;
  
  use v5.14;
  use warnings;
  
  use Carp;
  
  # XS code is part of XS::Parse::Sublike
  require XS::Parse::Sublike;
  
  =head1 NAME
  
  C<Sublike::Extended> - enable extended features when parsing C<sub>-like syntax
  
  =head1 SYNOPSIS
  
  =for highlighter language=perl
  
     use v5.26;
     use Sublike::Extended;
     use experimental 'signatures';
  
     extended sub greet (:$name = "world") {
        say "Hello, $name";
     }
  
     greet( name => $ENV{USER} );
  
  Or, I<since version 0.29:>
  
     use v5.26;
     use Sublike::Extended 0.29 'sub';
     use experimental 'signatures';
  
     sub greet (:$name = "world") {
        say "Hello, $name";
     }
  
     greet( name => $ENV{USER} );
  
  =head1 DESCRIPTION
  
  This module extends the syntax for declaring named or anonymous subroutines
  using Perl's builtin C<sub> keyword, or other similar keywords provided by
  third-party modules, to enable parsing of extra features.
  
  By default, this module provides a new keyword, L<C<extended>|/extended>,
  which parses the extra syntax required. Optionally I<since version 0.29>, this
  module can additionally take over the handling of the C<sub> keyword itself,
  allowing this extra syntax to be used without the C<extended> prefix keyword.
  As this ability may be surprising to unsuspecting readers, this is not done by
  default and must be explicitly requested with the C<sub> import argument:
  
     use Sublike::Extended 'sub';
  
  On Perl 5.38 or above, this can also take over handling of the C<method>
  keyword when using C<feature 'class'>.
  
     use Sublike::Extended 'method';
  
  Currently, the only extended features that are provided are related to the
  parsing of a subroutine signature. Since signatures are only available on Perl
  version 5.26 or later, this module is unlikely to be useful in earlier
  versions of Perl.
  
  =head2 Named parameters
  
  Extended subroutines can declare named parameters in the signature, after any
  positional ones. These take the form of a name prefixed by a colon character.
  The caller of such a function should pass values for these parameters by the
  usual name-value pair syntax that would be used for passing into a regular
  hash. Within the body of the subroutine the values passed into these are
  unpacked into regular lexical variables.
  
     sub colour (:$red, :$green, :$blue) {
        ... # $red, $green and $blue are available as regular lexicals
     }
  
     # argument order at the caller site is not important
     colour(green => 1, blue => 2, red => 3);
  
  Positional parameters I<can> be placed after optional positional ones, but in
  order to make use of them the caller would have to pass a value for every
  positional parameter including the optional ones first. This is unlikely to be
  very useful; if you want to have optional parameters and named parameters, use
  named optional ones after any I<mandatory> positional parameters.
  
  As with positional parameters, they are normally mandatory, but can be made
  optional by supplying a defaulting expression. If the caller fails to pass a
  value corresponding to an optional parameter, the default expression is
  evaluated and used instead.
  
     sub f (:$x0, :$x1, :$x2 = 0) { ... }
     # The caller must provide x0 and x1, but x2 is optional
  
  I<Since version 0.23> named parameters can be given defaulting expressions
  with the C<//=> or C<||=> operators, meaning their defaults apply also if the
  caller passed a present-but-undef, or present-but-false value.
  
     sub f (:$x0, :$x1, :$x2 //= 0) { ... }
     # $x2 will be set to 0 even if the caller passes  x2 => undef
  
  An optional slurpy hash or (I<since version 0.24>) slurpy array is also
  permitted after all of these. It will contain the values of any other
  name-value pairs given by the caller, after those corresponding to named
  parameters have already been extracted.
  
     sub g (:$alpha, :$beta, %rest) { ... }
  
     sub g (:$alpha, :$beta, @rest) { ... }
  
  In the case of a slurpy array, it will contain every argument value that was
  not consumed as a named parameter pair, in the original order passed by the
  caller, including any duplicates.
  
  =head2 Parameter Attributes
  
  Parameters to extended subroutines can use attribute syntax to apply extra
  attributes to individual parameters.
  
     sub info ($x :Attribute) { ... }
  
  Any attributes that are available are ones that have been previously
  registered with L<XS::Parse::Sublike> using its XS-level API. The particular
  behaviour of such an attribute would be defined by whatever module provided
  the attribute.
  
  =head1 KEYWORDS
  
  =head2 extended
  
     extended sub NAME (SIGNATURE...) { BODY... }
  
     extended sub (SIGNATURE...) { BODY... };
  
  This prefix keyword enables extra parsing features when handling a C<sub> (or
  other sub-like function keyword).
  
  This keyword can be freely mixed with other C<sub>-prefix keywords, such as
  C<async> from L<Future::AsyncAwait>
  
     async extended sub f (:$param) { ... }
  
  This can also be used with other keywords that provide C<sub>-like syntax,
  such as C<method> from L<Object::Pad> or the core C<use feature 'class'>.
  
     extended method f (:$param) { ... }
  
  =cut
  
  sub import
  {
     shift;
     $^H{"Sublike::Extended/extended"}++;
  
     my @rest = grep {
        $_ eq "sub"    ? ( $^H{"Sublike::Extended/extended-sub"}++, 0 ) :
        $_ eq "method" ? ( $^H{"Sublike::Extended/extended-method"}++, 0 ) :
                         1
     } @_;
  
     croak "Unrecognised import arguments: @rest" if @rest;
  }
  
  sub unimport
  {
     shift;
     delete $^H{"Sublike::Extended/extended"};
  
     my @rest = grep {
        $_ eq "sub"    ? ( delete $^H{"Sublike::Extended/extended-sub"}, 0 ) :
        $_ eq "method" ? ( delete $^H{"Sublike::Extended/extended-method"}, 0 ) :
                         1
     } @_;
  
     croak "Unrecognised unimport arguments: @rest" if @rest;
  }
  
  =head1 TODO
  
  =over 4
  
  =item *
  
  Support defined-or and true-or positional parameters even on versions of Perl
  before they were officially added (v5.38).
  
  =back
  
  =head1 AUTHOR
  
  Paul Evans <leonerd@leonerd.org.uk>
  
  =cut
  
  0x55AA;
